-- Уникальность хеша и бизнес-ключа, отсутствие NULL в обязательных полях.
SELECT count(*) AS n FROM (SELECT field_hk AS k FROM {{target:oil_dds__hub_field}} GROUP BY field_hk HAVING field_hk IS NULL OR count(*)>1 UNION ALL SELECT field_id AS k FROM {{target:oil_dds__hub_field}} GROUP BY field_id HAVING field_id IS NULL OR count(*)>1 UNION ALL SELECT field_hk AS k FROM {{target:oil_dds__hub_field}} WHERE load_dts IS NULL OR record_source IS NULL) q;
